const $=s=>document.querySelector(s);let ctx,original,current,name='Ejemplo MixLab',url,busy=false;
function audioContext(){return ctx||=new AudioContext();}
function status(text){$('#demoStatus').textContent=text;}
function lock(value){busy=value;$('#example').disabled=value;$('#localFile').disabled=value;$('#prepareControls').disabled=value||!original;$('#convert').disabled=value||!current;}
function wav(buffer){const channels=buffer.numberOfChannels,length=buffer.length,bytes=new ArrayBuffer(44+length*channels*2),v=new DataView(bytes),str=(at,s)=>[...s].forEach((c,i)=>v.setUint8(at+i,c.charCodeAt()));str(0,'RIFF');v.setUint32(4,36+length*channels*2,true);str(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,channels,true);v.setUint32(24,buffer.sampleRate,true);v.setUint32(28,buffer.sampleRate*channels*2,true);v.setUint16(32,channels*2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,length*channels*2,true);for(let ch=0;ch<channels;ch++){const data=buffer.getChannelData(ch);for(let i=0;i<length;i++){const s=Math.max(-1,Math.min(1,data[i]));v.setInt16(44+(i*channels+ch)*2,s<0?s*32768:s*32767,true);}}return new Blob([bytes],{type:'audio/wav'});}
function refresh(){if(!original)return;const instrumental=$('#cleanMode').value==='instrumental';current=audioContext().createBuffer(2,original.length,original.sampleRate);const left=original.getChannelData(0),right=original.getChannelData(Math.min(1,original.numberOfChannels-1));for(let c=0;c<2;c++){const data=current.getChannelData(c);for(let i=0;i<data.length;i++)data[i]=instrumental?(left[i]-right[i])*.7:(c===0?left[i]:right[i]);}$('#demoAudio').pause();if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(wav(current));$('#demoAudio').src=url;applyTone();$('#sourceName').textContent=name;lock(false);status(instrumental?'Escuchá la reducción y comparala con Original.':'Audio listo. Podés escucharlo y probar la descarga.');}
function applyTone(){const shift=Number($('#demoTone').value);$('#demoAudio').preservesPitch=false;$('#demoAudio').playbackRate=2**(shift/12);$('#demoToneValue').textContent=shift===0?'Original':`${shift>0?'+':''}${shift}`;}
$('#example').onclick=()=>{audioContext();const sr=24000,n=sr*12,b=ctx.createBuffer(2,n,sr);for(let ch=0;ch<2;ch++){const a=b.getChannelData(ch);for(let i=0;i<n;i++){const t=i/sr,p=t%.6;const center=.13*Math.sin(2*Math.PI*440*t)*(.5+.5*Math.sin(t*3));const backing=.15*Math.sin(2*Math.PI*(ch===0?130.81:164.81)*t)+.2*Math.sin(2*Math.PI*55*p)*Math.exp(-p*18);a[i]=center+backing;}}original=b;name='Ejemplo sintetizado · 12 segundos';$('#cleanMode').value='original';$('#demoTone').value=0;refresh();};
$('#localFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;lock(true);status('Abriendo tu archivo…');try{if(f.size>40*1024*1024)throw Error('Elegí un archivo de hasta 40 MB.');const b=await audioContext().decodeAudioData(await f.arrayBuffer());if(b.duration>600)throw Error('Elegí un archivo de hasta 10 minutos.');original=b;name=f.name;$('#cleanMode').value='original';$('#demoTone').value=0;refresh();}catch(err){status('No pudimos abrirlo. '+err.message);}finally{lock(false);e.target.value='';}};
$('#cleanMode').onchange=refresh;$('#demoTone').oninput=applyTone;$('#demoVolume').oninput=()=>{const v=Number($('#demoVolume').value);$('#demoVolumeValue').textContent=v+'%';$('#demoAudio').volume=v/100;};$('#demoAudio').volume=.7;
$('#videoUrl').onchange=()=>{if(!$('#videoUrl').value)return;try{const u=new URL($('#videoUrl').value);if(!['youtube.com','www.youtube.com','m.youtube.com','youtu.be'].includes(u.hostname))throw Error();status('Enlace reconocido para la demostración. Pulsá Probar con audio de ejemplo: no se descargará el video.');}catch{status('Pegá un enlace de YouTube válido o elegí un archivo local.');}};
async function render(){const ratio=2**(Number($('#demoTone').value)/12),offline=new OfflineAudioContext(2,Math.ceil(current.length/ratio),current.sampleRate),source=offline.createBufferSource(),gain=offline.createGain();source.buffer=current;source.playbackRate.value=ratio;gain.gain.value=Number($('#demoVolume').value)/100;source.connect(gain).connect(offline.destination);source.start();return offline.startRendering();}
async function mp3(buffer){const worker=new Worker('./mp3-worker.js');try{return await new Promise((resolve,reject)=>{worker.onmessage=e=>e.data.error?reject(Error(e.data.error)):resolve(e.data.blob);worker.onerror=()=>reject(Error('No se pudo iniciar el codificador MP3.'));const channels=[buffer.getChannelData(0).slice(),buffer.getChannelData(1).slice()];worker.postMessage({channels,sampleRate:buffer.sampleRate},channels.map(c=>c.buffer));});}finally{worker.terminate();}}
$('#convert').onclick=async()=>{if(!current||busy)return;lock(true);$('#convertStatus').textContent='Preparando tu archivo…';try{const format=$('#demoFormat').value,b=await render(),blob=format==='mp3'?await mp3(b):wav(b),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name.replace(/\.[^.]+$/,'').replace(/[^\p{L}\p{N} _-]/gu,'').slice(0,70)+' - demo.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(href),60000);$('#convertStatus').textContent='Archivo preparado. Revisá Descargas para guardarlo o cargarlo en tu repertorio.';}catch(e){$('#convertStatus').textContent='No se pudo convertir: '+e.message;}finally{lock(false);}};
